use thiserror::Error;

/// Errors arising across the secret boundary.
///
/// **Security Guarantee:** Error messages generated by this module strictly
/// omit raw credential material. Identifiers such as secret reference paths,
/// operation names, and hostnames may be included, but raw secret values are
/// never interpolated into error strings.
#[derive(Error, Debug, Clone, PartialEq, Eq)]
pub enum BoundaryError {
    #[error("Authorization policy denied request: {0}")]
    PolicyDenied(String),

    #[error("Secret reference not found: {0}")]
    SecretNotFound(String),

    #[error("Credential provider failure: {0}")]
    ProviderError(String),

    #[error("Operation is not allowed: {0}")]
    OperationNotAllowed(String),

    #[error("Destination violates security policy: {0}")]
    DestinationViolation(String),

    #[error("Blocked potential SSRF or forbidden network destination: {0}")]
    SsrfBlocked(String),

    #[error("Operation execution failed: {0}")]
    ExecutionFailed(String),

    #[error("Network transport failure: {0}")]
    TransportError(String),

    #[error("Serialization or schema error: {0}")]
    SerializationError(String),

    #[error("Invalid request parameters or payload: {0}")]
    InvalidRequest(String),

    #[error("Configuration error: {0}")]
    ConfigurationError(String),
}
